//! SQL is generated by the shared contract, with no adapter-local schema copies.
pub fn baseline_sql() -> anyhow::Result<String> {
    aml_warehouse::baseline_contract()?.sql_template()
}
pub fn schema_sql() -> anyhow::Result<String> {
    Ok(aml_warehouse::migration::sql_templates()?
        .into_iter()
        .map(|(_, sql)| sql)
        .collect())
}
